package com.anamcara.controller;
import com.anamcara.service.S3MediaService;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;import software.amazon.awssdk.services.s3.model.*;
@RestController public class MediaController{private final S3MediaService media;public MediaController(S3MediaService media){this.media=media;}@GetMapping({"/api/uploads/{key:.+}","/uploads/{key:.+}"})public ResponseEntity<StreamingResponseBody>get(@PathVariable String key){try{HeadObjectResponse head=media.head(key);StreamingResponseBody body=out->{try(var input=media.open(key)){input.transferTo(out);}};return ResponseEntity.ok().contentType(MediaType.parseMediaType(head.contentType())).contentLength(head.contentLength()).cacheControl(CacheControl.maxAge(java.time.Duration.ofHours(1))).body(body);}catch(S3Exception e){return ResponseEntity.notFound().build();}}}
